961:   if (p.side !== previousSide && p.isKeeper) {
962:     const nearest = g.players.filter(x => x.side === 'home').sort((a, c) => dist(a, p) - dist(c, p))[0];
963:     if (nearest) setControlled(g, nearest);
964:   }
