974:   const inMouth = b.y > mouth.top && b.y < mouth.bottom && b.z < GOAL.bar;
975:   if (b.x > FIELD.right + 9 && inMouth) { scoreGoal(g, 'home'); return; }
976:   if (b.x < FIELD.x - 9 && inMouth) { scoreGoal(g, 'away'); return; }
