978:     if (b.lastTouch?.side === 'home') setPiece(g, 'GOAL KICK', 'away', FIELD.right - 70, clamp(b.y, FIELD.cy - 70, FIELD.cy + 70), true);
979:     else setPiece(g, 'CORNER', 'home', FIELD.right - 10, b.y < FIELD.cy ? FIELD.y + 10 : FIELD.bottom - 10, false);
980:     return;
981:   }
982:   if (b.x < FIELD.x - 14) {
983:     if (b.lastTouch?.side === 'away') setPiece(g, 'GOAL KICK', 'home', FIELD.x + 70, clamp(b.y, FIELD.cy - 70, FIELD.cy + 70), true);
984:     else setPiece(g, 'CORNER', 'away', FIELD.x + 10, b.y < FIELD.cy ? FIELD.y + 10 : FIELD.bottom - 10, false);
