1036:   g.shake = 9; g.flash = 1; g.flashColor = side === 'home' ? '#c9ff3f' : '#ff4058';
1037:   g.kickoffSide = side === 'home' ? 'away' : 'home';
1038:   g.charging = false; g.charge = 0; g.trick = null;
1039:   $('#trickHud').classList.remove('is-active');
1040:   Sound.goal();
1041:   const scorer = g.ball.lastTouch?.side === side ? g.ball.lastTouch : g.players.find(p => p.side === side && !p.isKeeper);
1042:   const scorerName = scorer?.char?.name || (side === 'home' ? 'NOVA' : 'RIVAL');
1043:   const minutes = Math.min(90, Math.floor((g.elapsed / Math.max(1, g.cfg.time)) * 90));
1044:   const detail = g.lastShotDetail || pick(['TOP BINS', 'COOL FINISH', 'BACK OF THE NET']);
1045:   const styleBonus = 250 + g.combo * 50;
1046:   g.style += styleBonus;
1047:   if (g.combo > 0) g.combo = Math.min(9, g.combo + 1);
1048:   g.comboTimer = 5;
1049:   g.bestCombo = Math.max(g.bestCombo, g.combo);
