1055:   $('#goalStyle').textContent = `+${styleBonus} STYLE${g.combo > 1 ? ` · ×${g.combo} COMBO` : ''}`;
1056:   $('#goalBanner').classList.add('is-active');
1057:   spawnConfetti(g, 90, side === 'home' ? FIELD.right - 80 : FIELD.x + 80);
