1101:     { label: 'TUBES EARNED', value: `+${fmt(tubes)}` },
1102:     { label: g.mode === 'ranked' ? 'RANK POINTS' : 'BEST COMBO', value: g.mode === 'ranked' ? `${rpDelta >= 0 ? '+' : ''}${rpDelta} RP` : `×${g.bestCombo}` }
